<script setup lang="ts">
import {computed,ref,watch,onUnmounted,nextTick} from 'vue'
import {LayoutDashboard,BookOpen,BarChart3,Users,ShieldCheck,GitBranch,ArrowUpRight,ArrowRight,Download,Maximize,Minimize,Play,Pause,ChevronLeft,ChevronRight,X,Info,Landmark,Wallet,AlertTriangle,CheckCircle2,Briefcase,FileText} from 'lucide-vue-next'
import {data,latin,num,money,sum,months,colors,organization,aggregateFinance,auditTitles,saveCSV,type Registry,type FinanceRow,type AuditCase} from '../presentation/native/data'
import LiveOperations from '../presentation/native/LiveOperations.vue'
import InsightsExplorer from '../presentation/native/InsightsExplorer.vue'
import MetricValue from '../presentation/native/MetricValue.vue'
import RegionMap from '../presentation/native/RegionMap.vue'
import ExecutionFlow from '../presentation/native/ExecutionFlow.vue'
import RegistryPanel from '../presentation/native/RegistryPanel.vue'
import FamilyPanel from '../presentation/native/FamilyPanel.vue'
import AuditPanel from '../presentation/native/AuditPanel.vue'
import FinancialPanel from '../presentation/native/FinancialPanel.vue'
const props=defineProps<{view:string}>()
const tab=ref('overview'),role=ref('leader'),year=ref(2025),period=ref('all'),region=ref(''),agency=ref(''),expanded=ref(false),familyId=ref(data.families.find(f=>f.members.length>=3&&f.members.every(m=>m.source))?.id??data.families[0]!.id),auditInitial=ref(0),analysisCut=ref('measures')
const tabs=[{key:'overview',title:'Umumiy ko‘rinish',icon:LayoutDashboard},{key:'registry',title:'Choralar reyestri',icon:BookOpen},{key:'finance',title:'Idoralar va hududlar',icon:BarChart3},{key:'family',title:'Fuqaro va oila',icon:Users},{key:'audit',title:'Nazorat markazi',icon:ShieldCheck},{key:'services',title:'Huquqlar va xizmatlar',icon:Briefcase},{key:'flow',title:'Ijro oqimi',icon:GitBranch}]
const visibleTabs=computed(()=>role.value==='citizen'?tabs.filter(t=>['family','services'].includes(t.key)):tabs)
const selectedMonths=computed(()=>period.value==='all'?months.map((_,i)=>i):period.value.startsWith('upto')?months.map((_,i)=>i).filter(i=>i<=+period.value.slice(4)):period.value.startsWith('q')?months.map((_,i)=>i).filter(i=>Math.floor(i/3)===+period.value.slice(1)): [+period.value])
const finance=computed(()=>data.finance.filter(l=>!agency.value||l.o===agency.value).map(l=>aggregateFinance(l,year.value,region.value,selectedMonths.value)).filter(r=>r.total||r.count))
const total=computed(()=>sum(finance.value.map(x=>x.total)))
const monthly=computed(()=>months.map((_,i)=>sum(finance.value.map(x=>x.values[i]?.s??0))))
const maxMonthly=computed(()=>Math.max(...monthly.value,1))
const shares=computed(()=>Object.entries(data.organizations).map(([key,name])=>({key,name,amount:sum(finance.value.filter(r=>r.line.o===key).map(r=>r.total))})).filter(x=>x.amount).sort((a,b)=>b.amount-a.amount))
const ring=computed(()=>{let at=0;return 'conic-gradient('+shares.value.map((s,i)=>{const start=at;at+=s.amount/Math.max(total.value,1)*100;return colors[i%colors.length]+' '+start+'% '+at+'%'}).join(',')+')'})
const regional=computed(()=>data.regions.map((name,i)=>({name,i,total:sum(data.finance.filter(l=>!agency.value||l.o===agency.value).map(l=>aggregateFinance(l,year.value,String(i),selectedMonths.value).total))})))
const scope=computed(()=>region.value===''?'Respublika':latin(data.regions[+region.value]))
const dataLabel=computed(()=>tab.value==='finance'&&analysisCut.value==='people'?'2025-yil nafaqa bazasi':year.value===2025&&period.value==='all'?'2025-yil manba ko‘rsatkichlari':year.value!==2025?'Namunaviy yil ko‘rsatkichlari':'Oylik taqsimot — namunaviy')
const topMeasures=computed(()=>[...finance.value].sort((a,b)=>b.total-a.total).slice(0,5))
const root=ref<HTMLElement|null>(null),dialog=ref<HTMLElement|null>(null)
type Drawer={kind:'registry';item:Registry}|{kind:'finance';item:FinanceRow}|{kind:'audit';item:AuditCase;category:number}|{kind:'receipt';title:string;lines:string[]}|{kind:'methodology'}
const drawer=ref<Drawer|null>(null),reviewOwner=ref(''),reviewNote=ref(''),reviewState=ref('Tekshirilmoqda'),reviewMessage=ref('')
let previousFocus:HTMLElement|null=null
function open(value:Drawer){previousFocus=document.activeElement as HTMLElement;drawer.value=value;reviewMessage.value='';reviewNote.value='';reviewOwner.value='';reviewState.value='Tekshirilmoqda';if(value.kind==='audit'){try{const stored=JSON.parse(localStorage.getItem('nasp-social-review-'+value.category+'-'+value.item.id)??'null');if(stored){reviewOwner.value=stored.owner;reviewNote.value=stored.note;reviewState.value=stored.state}}catch{}}nextTick(()=>dialog.value?.focus())}
function close(){drawer.value=null;previousFocus?.focus()}
function trap(event:KeyboardEvent){if(event.key==='Escape'){close();return}if(event.key!=='Tab'||!dialog.value)return;const nodes=[...dialog.value.querySelectorAll<HTMLElement>('button, input, textarea, select, a[href]')].filter(el=>!el.hasAttribute('disabled'));const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
function saveReview(){if(drawer.value?.kind!=='audit')return;if(!reviewOwner.value.trim()||!reviewNote.value.trim()){reviewMessage.value='Mas’ul va tekshiruv qaydini kiriting.';return}try{localStorage.setItem('nasp-social-review-'+drawer.value.category+'-'+drawer.value.item.id,JSON.stringify({owner:reviewOwner.value,note:reviewNote.value,state:reviewState.value}));reviewMessage.value='Namunaviy ko‘rib chiqish qaydi shu brauzerda saqlandi.'}catch{reviewMessage.value='Qaydni saqlab bo‘lmadi.'}}
function go(value:string){tab.value=value;if(value==='finance'&&analysisCut.value==='people'){year.value=2025;agency.value=''};nextTick(()=>{root.value?.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});if(!expanded.value&&window.innerWidth<1280)root.value?.scrollIntoView({block:'start',behavior:'smooth'})})}
function resetFilters(){year.value=2025;period.value='all';region.value=agency.value=''}
function chooseRole(){stopTour();go(role.value==='citizen'||role.value==='staff'?'family':'overview')}
function openFamily(id:string){familyId.value=id;go('family')}
function openAudit(index:number){auditInitial.value=index;go('audit')}
function exportDashboard(){saveCSV('Yagona_platforma_hisoboti.csv',[['Davr',String(year.value),period.value],['Hudud',scope.value],['Manba',dataLabel.value],['Chora','Idora','Summa mlrd'],...finance.value.map(x=>[latin(x.line.n),organization(x.line.o),x.total])])}
function printReceipt(){window.print()}
const receiptText=computed(()=>drawer.value?.kind==='receipt'?drawer.value.lines:[])
const detailsFinanceRegions=computed(()=>drawer.value?.kind==='finance'?data.regions.map((name,i)=>({name,i,value:aggregateFinance((drawer.value as {kind:'finance';item:FinanceRow}).item.line,year.value,String(i),selectedMonths.value).total})):[])
const tourSteps=[{tab:'overview',title:'Respublika miqyosidagi natija',text:'Yagona hisob, moliyaviy ko‘lam va e’tibor talab qiladigan holatlar.'},{tab:'registry',title:'Choradan mas’ul idoragacha',text:'Istalgan tur yoki yo‘nalishni tanlang, choraning kartochkasini oching.'},{tab:'finance',title:'Hudud va tuman kesimi',text:'Idora, davr va hududni o‘zgartirib natijalarni solishtiring.'},{tab:'family',title:'Bir oilaga ko‘rsatilgan ko‘mak',text:'Oila a’zosini tanlang, oylik tarix va hujjatlarni ko‘ring.'},{tab:'audit',title:'Muammo qanday aniqlanadi?',text:'Signalni tanlang, hudud va holatdan oylik dalilga o‘ting.'},{tab:'flow',title:'Tizimning ishlash jarayoni',text:'To‘g‘ri, takroriy yoki kodsiz xabarni bosqichma-bosqich tekshiring.'},{tab:'services',title:'Fuqaro uchun keyingi qadam',text:'Huquqlar, mavjud ko‘mak va yangi xizmatga namunaviy ariza.'}]
const tourIndex=ref(-1),tourPlaying=ref(false);let tourTimer:ReturnType<typeof setInterval>|undefined
function stopTour(){clearInterval(tourTimer);tourPlaying.value=false}
function tourStep(index:number){tourIndex.value=Math.max(0,Math.min(tourSteps.length-1,index));role.value='leader';go(tourSteps[tourIndex.value]!.tab);if(tourIndex.value===tourSteps.length-1)stopTour()}
function toggleTour(){if(tourPlaying.value){stopTour();return}resetFilters();tourStep(tourIndex.value<0||tourIndex.value===tourSteps.length-1?0:tourIndex.value);tourPlaying.value=true;tourTimer=setInterval(()=>tourStep(tourIndex.value+1),17000)}
function explore(event:PointerEvent){if(tourPlaying.value&&!(event.target as HTMLElement).closest('.tour-control'))stopTour()}
watch(()=>props.view,v=>go(v==='platform-family'?'family':v==='platform-control'?'audit':v==='platform-execution'?'flow':'overview'),{immediate:true})
onUnmounted(stopTour)
</script>

<template><div ref="root" class="native-platform" :class="{expanded}" @pointerdown="explore"><header class="np-header"><div><div class="np-eyebrow"><span></span>IJTIMOIY QO‘LLAB-QUVVATLASH</div><h1>Yagona ijtimoiy platforma</h1><p>Davlat ko‘magi — umumiy hisobdan har bir fuqaro natijasigacha</p></div><div class="np-header-actions"><select v-model="role" aria-label="Namoyish ko‘rinishi" @change="chooseRole"><option value="leader">Rahbar ko‘rinishi</option><option value="staff">Mas’ul xodim</option><option value="citizen">Fuqaro kabineti</option></select><button class="np-button" aria-label="Ma’lumotlar izohi" @click="open({kind:'methodology'})"><Info :size="16"/></button><button class="np-button" @click="expanded=!expanded"><component :is="expanded?Minimize:Maximize" :size="15"/>{{ expanded?'Yopish':'Taqdimot ekrani' }}</button><button class="np-button primary tour-control" @click="toggleTour"><component :is="tourPlaying?Pause:Play" :size="14"/>{{ tourPlaying?'Pauza':'Taqdimotni boshlash' }}</button></div></header><nav class="np-tabs" aria-label="Platforma bo‘limlari"><button v-for="item in visibleTabs" :key="item.key" :aria-current="tab===item.key?'page':undefined" :class="{active:tab===item.key}" @click="go(item.key)"><component :is="item.icon" :size="16"/>{{ item.title }}<span v-if="item.key==='audit'" class="tab-count">6</span></button></nav><div v-if="tourIndex>=0" class="np-tour tour-control"><span class="tour-number">{{ tourIndex+1 }}<small>/ {{ tourSteps.length }}</small></span><div><b>{{ tourSteps[tourIndex]?.title }}</b><p>{{ tourSteps[tourIndex]?.text }}</p></div><div class="tour-dots"><button v-for="(item,i) in tourSteps" :key="item.tab" :aria-label="item.title" :class="{active:i===tourIndex}" @click="stopTour();tourStep(i)"></button></div><button class="icon-button" :disabled="tourIndex===0" aria-label="Oldingi bosqich" @click="stopTour();tourStep(tourIndex-1)"><ChevronLeft :size="18"/></button><button class="icon-button" :disabled="tourIndex===tourSteps.length-1" aria-label="Keyingi bosqich" @click="stopTour();tourStep(tourIndex+1)"><ChevronRight :size="18"/></button><button class="icon-button" aria-label="Taqdimotni yakunlash" @click="stopTour();tourIndex=-1"><X :size="17"/></button></div><div v-if="['overview','finance'].includes(tab)" class="np-global-filters"><div v-if="!(tab==='finance'&&analysisCut==='people')" class="period-label"><span>Hisobot davri</span><select v-model.number="year" aria-label="Hisobot yili"><option :value="2024">2024</option><option :value="2025">2025</option><option :value="2026">2026</option></select></div><div class="np-segment"><button v-for="[key,title] in [['all','Yil'],['q0','I chorak'],['q1','II chorak'],['q2','III chorak'],['q3','IV chorak']]" :key="key" :class="{active:period===key}" @click="period=key!">{{ title }}</button></div><select v-if="!(tab==='finance'&&analysisCut==='people')" v-model="agency" aria-label="Hisobot idorasi"><option value="">Barcha idoralar</option><option v-for="(name,key) in data.organizations" :key="key" :value="key">{{ latin(name) }}</option></select><select v-model="region" aria-label="Hisobot hududi"><option value="">Respublika</option><option v-for="(name,i) in data.regions" :key="i" :value="String(i)">{{ latin(name) }}</option></select><button class="icon-button" aria-label="Filtrlarni tozalash" @click="resetFilters"><X :size="14"/></button><span class="np-data-label" :class="year===2025&&period==='all'?'verified':'sample'"><i></i>{{ dataLabel }}</span></div><main :key="tab" class="np-view"><template v-if="tab==='overview'"><LiveOperations/><section class="executive-metrics"><button class="executive-metric" @click="go('finance')"><div><span class="metric-icon blue"><Wallet :size="19"/></span><ArrowUpRight :size="15"/></div><p>Hisobga olingan davlat ko‘magi</p><strong><MetricValue :value="total/1000" :decimals="1"/><small>trln so‘m</small></strong><footer><span class="np-tag blue">{{ scope }}</span><span>{{ year }}-yil · {{ selectedMonths.length }} oy</span></footer></button><button class="executive-metric" @click="analysisCut='people';go('finance')"><div><span class="metric-icon teal"><Users :size="19"/></span><ArrowUpRight :size="15"/></div><p>Nafaqa oluvchilar</p><strong><MetricValue :value="data.demographics.persons"/></strong><footer><span class="np-tag green">Nafaqa bazasi</span><span>2025-yil · respublika</span></footer></button><button class="executive-metric" @click="go('registry')"><div><span class="metric-icon purple"><BookOpen :size="19"/></span><ArrowUpRight :size="15"/></div><p>Davlat qo‘llab-quvvatlash choralari</p><strong><MetricValue :value="data.registryTotal"/><small>chora</small></strong><footer><span class="np-tag purple">{{ data.agencies.length }} idora</span><span>{{ data.registry.length }} reyestr yozuvi</span></footer></button><button class="executive-metric attention" @click="openAudit(0)"><div><span class="metric-icon coral"><AlertTriangle :size="19"/></span><ArrowUpRight :size="15"/></div><p>Ortiqcha to‘lov signali</p><strong><MetricValue :value="549"/><small>mln so‘m</small></strong><footer><span class="np-tag red">Tekshirish zarur</span><span>2 signal turi · 2025</span></footer></button></section><div class="executive-grid"><section class="np-card monthly-card"><div class="np-card-heading"><div><h3>Davlat ko‘magining oylik dinamikasi</h3><p>{{ year }}-yil · {{ scope }} · mlrd so‘m</p></div><div class="mini-total"><b>{{ money(total*1e9) }}</b><small>Tanlangan davr</small></div></div><div class="np-month-chart"><button v-for="(value,i) in monthly" :key="i" :class="{selected:period===String(i),dim:!selectedMonths.includes(i)}" :title="months[i]+': '+money(value*1e9)+' so‘m'" @click="period=period===String(i)?'all':String(i)"><b>{{ num(value,0) }}</b><i :style="{height:Math.max(2,value/maxMonthly*100)+'%',animationDelay:i*55+'ms'}"/><span>{{ months[i] }}</span></button></div><div class="chart-foot"><span><i></i>Ko‘rsatilgan ko‘mak</span><small>Oyni bosib davrni tanlang · oylik taqsimot namunaviy</small></div></section><section class="np-card agency-card"><div class="np-card-heading"><div><h3>Idoralar ulushi</h3><p>Tanlangan summa taqsimoti</p></div><Landmark :size="17"/></div><div class="agency-donut"><div class="donut" :style="{background:shares.length?ring:'#edf1f7'}"><div><strong>{{ shares.length }}</strong><span>idora</span></div></div><div class="donut-legend"><button v-for="(item,i) in shares" :key="item.key" @click="agency=agency===item.key?'':item.key"><i :style="{background:colors[i%colors.length]}"/><span>{{ organization(item.key).replace('Ijtimoiy himoya milliy agentligi','IHMA') }}</span><b>{{ num(item.amount/Math.max(total,1)*100,1) }}%</b></button><p v-if="!shares.length">Tanlov bo‘yicha ma’lumot yo‘q.</p></div></div><button class="card-link" @click="go('finance')">Choralar bo‘yicha ochish <ArrowRight :size="14"/></button></section></div><InsightsExplorer :year="year" :agency="agency" :period="period" :selected-months="selectedMonths" @period="period=$event" @region="region=$event"/><div class="executive-grid second-row"><section class="np-card"><div class="np-card-heading"><div><h3>Hududlar bo‘yicha ko‘mak</h3><p>IHMA · hududni tanlab batafsil oching</p></div><button class="np-button" @click="analysisCut='regions';go('finance')">Batafsil <ArrowUpRight :size="13"/></button></div><RegionMap :values="regional.map(r=>r.total*1e9)" :selected="region" @select="region=$event"/><div v-if="region!==''" class="selected-region"><div><b>{{ scope }}</b><p>{{ money(regional[+region]?.total!*1e9) }} so‘m</p></div><button class="np-button primary" @click="analysisCut='people';go('finance')">Tumanlar kesimi <ArrowRight :size="13"/></button></div></section><section class="np-card"><div class="np-card-heading"><div><h3>E’tibor talab qiladigan holatlar</h3><p>Nafaqa bazasidagi nazorat signallari</p></div><ShieldCheck :size="18"/></div><button v-for="(item,i) in data.audit.slice(0,4)" :key="item.k" class="signal-link" @click="openAudit(i)"><span class="signal-dot" :class="i<2?'red':'amber'"><AlertTriangle :size="16"/></span><span><b>{{ auditTitles[i] }}</b><small>{{ i<2?'Ortiqcha to‘lov signali':'Asosini tekshirish kerak' }}</small></span><strong>{{ num(item.n) }}</strong><ChevronRight :size="15"/></button><div class="positive-note"><CheckCircle2 :size="17"/><p>Bir oylik to‘lovning ikki oluvchiga bo‘linishi alohida kuzatiladi. Bu avtomatik ortiqcha to‘lov hisoblanmaydi.</p></div><button class="card-link" @click="go('audit')">Barcha 6 signal turini ko‘rish <ArrowRight :size="14"/></button></section></div><section class="np-card"><div class="np-card-heading"><div><h3>Eng katta ko‘mak yo‘nalishlari</h3><p>Tanlangan davr va hudud bo‘yicha</p></div><button class="np-button" @click="exportDashboard"><Download :size="14"/>Hisobot</button></div><div class="top-measures"><button v-for="(row,i) in topMeasures" :key="row.line.id" @click="open({kind:'finance',item:row})"><span>{{ String(i+1).padStart(2,'0') }}</span><div><b>{{ latin(row.line.n) }}</b><small>{{ organization(row.line.o) }}</small></div><i><em :style="{width:row.total/(topMeasures[0]?.total||1)*100+'%'}"/></i><strong>{{ money(row.total*1e9) }}</strong><ArrowUpRight :size="15"/></button></div></section></template><RegistryPanel v-else-if="tab==='registry'" @open="open({kind:'registry',item:$event})"/><FinancialPanel v-else-if="tab==='finance'" :key="analysisCut" :initial="analysisCut" :year="year" :region="region" :agency="agency" :selected-months="selectedMonths" @region="region=$event" @open="open({kind:'finance',item:$event})" @family="openFamily" @cut="analysisCut=$event;if($event==='people'){year=2025;agency=''}"/><FamilyPanel v-else-if="tab==='family'||tab==='services'" :key="tab" :family-id="familyId" :role="role" :services="tab==='services'" @family="familyId=$event" @services="go('services')" @receipt="open({kind:'receipt',...$event})"/><AuditPanel v-else-if="tab==='audit'" :initial="auditInitial" @open="open({kind:'audit',...$event})"/><ExecutionFlow v-else-if="tab==='flow'" @passport="go('family')"/></main><footer class="np-footer"><span>NASP · Yagona ijtimoiy platforma</span><span>Namoyish muhiti · manba va namunaviy ko‘rsatkichlar ajratilgan</span><button @click="open({kind:'methodology'})">Ma’lumotlar izohi <Info :size="12"/></button></footer>
<div v-if="drawer" class="np-overlay" @click.self="close"><section ref="dialog" class="np-dialog main-dialog" :class="{'receipt-dialog':drawer.kind==='receipt'}" role="dialog" aria-modal="true" aria-labelledby="detail-heading" tabindex="-1" @keydown="trap"><header><div><span class="np-eyebrow">{{ drawer.kind==='audit'?'NAZORAT DALILI':drawer.kind==='registry'?'CHORA KARTOCHKASI':drawer.kind==='receipt'?'NAMUNAVIY HUJJAT':'BATAFSIL MA’LUMOT' }}</span><h2 id="detail-heading">{{ drawer.kind==='registry'?latin(drawer.item.n):drawer.kind==='finance'?latin(drawer.item.line.n):drawer.kind==='audit'?'Holat #'+drawer.item.id:drawer.kind==='receipt'?drawer.title:'Ma’lumotlar qamrovi va hisoblash' }}</h2></div><button class="icon-button" aria-label="Tafsilotni yopish" @click="close"><X :size="21"/></button></header><template v-if="drawer.kind==='registry'"><div class="detail-tags"><span class="np-tag blue">{{ latin(data.types[drawer.item.ti]) }}</span><span class="np-tag purple">{{ latin(data.fields[drawer.item.fi]) }}</span></div><dl class="detail-list"><dt>Mas’ul idora</dt><dd>{{ latin(drawer.item.o) }}</dd><dt>Aholi toifasi</dt><dd>{{ latin(drawer.item.cn) }}</dd><dt>Huquqiy asos</dt><dd>{{ latin(drawer.item.b)||'Manba yozuvida alohida ko‘rsatilmagan' }}</dd></dl><h3>Shu toifa va yo‘nalishdagi choralar</h3><button v-for="r in data.registry.filter(x=>x.ci===(drawer as any).item.ci&&x.fi===(drawer as any).item.fi&&x.id!==(drawer as any).item.id).slice(0,8)" :key="r.id" class="related-measure" @click="open({kind:'registry',item:r})"><span>{{ latin(r.n) }}</span><ChevronRight :size="15"/></button></template><template v-else-if="drawer.kind==='finance'"><p class="detail-subtitle">{{ organization(drawer.item.line.o) }} · {{ year }} · {{ scope }}</p><div class="detail-stats"><div><span>Ko‘rsatilgan ko‘mak</span><strong>{{ money(drawer.item.total*1e9) }}</strong><small>so‘m</small></div><div><span>{{ drawer.item.line.k==='m'?'O‘rtacha oylik oluvchi':'Oluvchilar' }}</span><strong>{{ drawer.item.line.cnt===null?'—':num(drawer.item.count) }}</strong></div></div><h3>Oylar bo‘yicha</h3><div class="detail-months"><div v-for="(value,i) in drawer.item.values" :key="i"><span>{{ months[i] }}</span><b>{{ money(value.s*1e9) }}</b><small>{{ num(value.c) }} oluvchi</small></div></div><h3>Hududlar bo‘yicha</h3><p v-if="!detailsFinanceRegions.some(x=>x.value)" class="np-note">Bu chora uchun hudud kesimi manbada berilmagan.</p><button v-for="r in detailsFinanceRegions.filter(x=>x.value)" :key="r.i" class="related-measure" @click="region=String(r.i);close();go('finance')"><span>{{ latin(r.name) }}</span><b>{{ money(r.value*1e9) }}</b><ArrowRight :size="13"/></button><template v-if="drawer.item.line.id==='w1'"><h3>Yo‘nalishlar bo‘yicha oluvchilar</h3><div v-for="[name,count] in data.womenSubsidies" :key="name" class="related-measure"><span>{{ latin(name) }}</span><b>{{ num(count) }}</b></div></template><h3>Shu chorani olgan namunaviy oilalar</h3><button v-for="f in data.families.filter(f=>f.members.some(m=>m.rows.some(r=>r.id===(drawer as any).item.line.id))).slice(0,20)" :key="f.id" class="related-measure" @click="close();openFamily(f.id)"><span>{{ latin(f.members[0]?.name) }}</span><ArrowUpRight :size="14"/></button><p class="np-note">{{ dataLabel }}. Oila F.I.Sh.lari shartli.</p></template><template v-else-if="drawer.kind==='audit'"><span class="np-tag" :class="drawer.category<3?'red':drawer.category===3?'amber':'blue'">{{ auditTitles[drawer.category] }}</span><p class="detail-subtitle">{{ latin(data.regions[data.regionMap[drawer.item.ri]!]) }}{{ drawer.item.age?' · '+drawer.item.age+' yosh':'' }}</p><p class="np-note">{{ latin(data.audit[drawer.category]?.why) }}</p><div v-if="drawer.item.m" class="np-table-wrap"><table class="np-table audit-evidence"><thead><tr><th>Nafaqa</th><th v-for="m in months" :key="m">{{ m }}</th></tr></thead><tbody><tr v-for="[t,values] in drawer.item.m" :key="t"><td>{{ latin(data.benefitTypes[t]) }}</td><td v-for="(value,i) in values" :key="i" :class="value>=Math.min(...values.filter(v=>v>0))*1.8?'evidence-alert':''">{{ value?num(value/1000):'—' }}</td></tr></tbody></table></div><p v-if="drawer.item.m" class="np-note">Ming so‘mda. Rang bilan odatiy to‘lovdan sezilarli yuqori bo‘lgan oy ajratilgan.</p><div v-else class="detail-stats"><div><span>Vakil orqali oluvchilar</span><strong>{{ drawer.item.n }}</strong></div><div><span>Yillik summa</span><strong>{{ money(drawer.item.s??0) }}</strong></div></div><form class="review-form" @submit.prevent="saveReview"><h3>Mas’ul ko‘rib chiqishi</h3><label>Mas’ul<input v-model="reviewOwner" placeholder="Mas’ul xodim yoki bo‘lim"/></label><label>Ko‘rib chiqish holati<select v-model="reviewState"><option>Tekshirilmoqda</option><option>Qo‘shimcha dalil kerak</option><option>Tekshiruv qaydi tayyor</option></select></label><label>Dalil va izoh<textarea v-model="reviewNote" rows="3" placeholder="Tekshirilgan holat va asosni yozing"/></label><button class="np-button primary" type="submit">Qaydni saqlash</button><p v-if="reviewMessage" class="np-note" role="status">{{ reviewMessage }}</p><small>Bu qayd to‘lov yoki fuqaroga ko‘makni o‘zgartirmaydi.</small></form></template><template v-else-if="drawer.kind==='receipt'"><div class="receipt-paper"><span>YAGONA IJTIMOIY PLATFORMA</span><h3>{{ drawer.title }}</h3><p v-for="(line,i) in receiptText" :key="i">{{ line }}</p></div><button class="np-button primary no-print" @click="printReceipt"><FileText :size="14"/>Chop etish / PDF</button></template><template v-else><div class="method-grid"><article><span class="np-tag green">Manba ko‘rsatkichi</span><h3>2025-yil</h3><p>Idoralar kesimidagi yillik summa va son, IHMAning 14 hududi bo‘yicha vedomost ijrosi, 37 idora va 577 chora yig‘masi.</p></article><article><span class="np-tag green">Nafaqa bazasi</span><h3>Fuqaro va nazorat</h3><p>701 468 nafaqa oluvchi, 12 oy, 208 tuman, shaxsi yashirilgan pasportlar va nazorat dalillari.</p></article><article><span class="np-tag amber">Namunaviy</span><h3>Model va jarayonlar</h3><p>2024 va 2026-yillar, oylik taqsimotning ayrim qismlari, idoralararo signallar, tavsiyalar va arizalar.</p></article></div><h3>Qamrov va talqin</h3><ul class="method-list"><li>Reyestrda 613 ta idora-chora yozuvi bor. 577 — manbadagi yig‘ma chora soni.</li><li>Moliyaviy jadvalda 44 ta chora mavjud. Reyestrdagi barcha choralar uchun summa berilmagan.</li><li>273 ta oila pasporti manbadagi namuna doirasida. To‘liq respublika shaxslar ro‘yxati emas.</li><li>Turli choralar, hududlar yoki oylardagi oluvchilar sonini qo‘shib, noyob shaxslar sonini chiqarish mumkin emas.</li><li>Manbadagi raqamlar saqlangan. Birlamchi davlat bazasi mustaqil tekshirilmagan.</li><li>Namoyish rollari haqiqiy vakolatlar yoki OneID autentifikatsiyasi o‘rnini bosmaydi.</li></ul><details><summary>Manbadagi to‘liq metodologiya matni</summary><p class="source-methodology">{{ latin(data.methodology.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ')) }}</p></details></template></section></div></div></template>
